#include "ovl_patches.hpp"
#include "../../RecompiledFuncs/recomp_overlays.inl"

#include "librecomp/overlays.hpp"

// Registers the recompiled game's code sections/overlays with the runtime.
// recomp_overlays.inl is GENERATED by N64Recomp (Phase 2); this will not compile
// until that file exists.
void wcw::register_wcw_overlays() {
    recomp::overlays::overlay_section_table_data_t sections {
        .code_sections = section_table,
        .num_code_sections = ARRLEN(section_table),
        .total_num_sections = num_sections,
    };

    recomp::overlays::overlays_by_index_t overlays {
        .table = overlay_sections_by_index,
        .len = ARRLEN(overlay_sections_by_index),
    };

    recomp::overlays::register_overlays(sections, overlays);
}

// The hack copies 0x320 bytes of jump trampolines into bss at 0x8009FDD0 with plain CPU
// stores (rom 0x2FC6444, see syms/dump.toml "hack_tramp"), so no DMA ever names that section.
// Map it at boot; the recompiled stubs are static code and need no bytes in place.
// The hack's main code block is read from rom 0x2FA1704 into 0x80364B30 (0x25380 bytes) in
// 0x100-byte pieces, so no single DMA covers the section either.
extern "C" void load_section_by_rom(uint32_t rom, int32_t ram);
extern "C" void recomp_load_extra_boot_overlays() {
    load_section_by_rom(0x2FA1704, 0x80364B30);   // hack_far
    load_section_by_rom(0x2FC6444, 0x8009FDD0);   // hack_tramp (lies inside hack_far's rom range)
    // The match-time block (rom 0x2F1A9D4, 0x1100 bytes) is read into a heap buffer by hack code in
    // ovl_b (0x8011E424) when a match starts. shortcut: assumes the allocator always hands out
    // 0x801BB3A0 for it; if a match type ever logs "Failed to find function at 0x801Bxxxx", map it
    // from the DMA hook instead.
    load_section_by_rom(0x2F1A9D4, 0x801BB3A0);   // hack_match (the DMA hook in pi.cpp moves it if a match loads it elsewhere)
}
